(()=>{const plot=document.getElementById('fieldplot'),status=document.getElementById('field-status'),ns='http://www.w3.org/2000/svg';let yaw=.5,pitch=.45;function project(p){const x=Math.cos(yaw)*p[0]-Math.sin(yaw)*p[1],y=Math.sin(yaw)*p[0]+Math.cos(yaw)*p[1];return[400+70*x,220-70*(Math.cos(pitch)*p[2]-Math.sin(pitch)*y)];}function mark(tag,attrs){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);plot.append(e);return e;}function line(a,b,color,width=2,extra={}){const p=project(a),q=project(b);return mark('line',{x1:p[0],y1:p[1],x2:q[0],y2:q[1],stroke:color,'stroke-width':width,...extra});}function draw(){const model=CondensedGeometry.geometry(CondensedReview);plot.replaceChildren();for(const ring of model.rings)for(let i=1;i<ring.length;i++)line(ring[i-1],ring[i],'#8798b4',1);for(let i=0;i<8;i++){const t=i*Math.PI/4;line([Math.cos(t),Math.sin(t),-2],[Math.cos(t),Math.sin(t),2],'#8798b4',1);}for(const g of [...model.fieldGlyphs,...model.currentGlyphs]){const p=project(g.originMM),q=project(g.endpointMM),color=g.kind==='surface-K'?'#f4c35b':'#60b5ff';if(g.zero){mark('circle',{cx:p[0],cy:p[1],r:2,fill:'#ddd','data-zero-kind':g.kind});continue;}const shaft=line(g.originMM,g.endpointMM,color,2,{'data-glyph-kind':g.kind});shaft.dataset.source=JSON.stringify(g);const dx=q[0]-p[0],dy=q[1]-p[1],length=Math.hypot(dx,dy);if(length>1e-8){const head=Math.min(7,length*.3),ux=dx/length,uy=dy/length;mark('path',{d:`M ${q[0]-head*ux-head*.45*uy} ${q[1]-head*uy+head*.45*ux} L ${q[0]} ${q[1]} L ${q[0]-head*ux+head*.45*uy} ${q[1]-head*uy-head*.45*ux}`,stroke:color,fill:'none','stroke-width':2});}}mark('line',{x1:50,y1:400,x2:120,y2:400,stroke:'white','stroke-width':3});const label=mark('text',{x:50,y:385,fill:'white',style:'font:'+(14*800/Math.max(1,plot.clientWidth))+'px system-ui'});label.textContent='1 mm';status.textContent=model.uniqueHomogeneousState?'Same spatial scale on all axes. Field and current glyphs use the separately declared value scales.':model.note;window.CondensedFieldReview={model,yaw,pitch,spatialGain:70};}for(const id of ['temperature','field'])document.getElementById(id).addEventListener('change',draw);for(const id of ['boundary','reset'])document.getElementById(id).addEventListener('click',draw);document.getElementById('turn-field').onclick=()=>{yaw+=.3;draw();};document.getElementById('tilt-field').onclick=()=>{pitch+=.25;if(pitch>1.2)pitch=.2;draw();};document.getElementById('reset-field').onclick=()=>{yaw=.5;pitch=.45;draw();};new ResizeObserver(draw).observe(plot);draw();})();
